using System.Globalization;
using VinayakaAgencies.Application.Common;
using VinayakaAgencies.Domain.Abstractions;
using VinayakaAgencies.Domain.Einvoicing;
using VinayakaAgencies.Domain.Trade;

namespace VinayakaAgencies.Application.Einvoicing;

/// <summary>
/// Generates and maintains e-way bills (phase-6-einvoice-eway.md §2).
/// </summary>
/// <remarks>
/// <para>
/// A bill is generated by IRN when the invoice has one, and directly otherwise. Both land in the same
/// row, because the portal makes no lasting distinction — the IRN route simply saves re-sending
/// invoice detail the portal already holds.
/// </para>
/// <para>
/// Validity is whatever the portal grants, not whatever we calculate. <see cref="EwayBillValidity"/>
/// exists so the expected expiry can be shown before generation and asserted in tests, but once the
/// portal answers, its expiry is the one stored. Two sources of truth for an expiry that a roadside
/// officer checks is not a disagreement worth having.
/// </para>
/// </remarks>
public sealed class EwayBillService(
    IUnitOfWork unitOfWork,
    ICompanyContext companyContext,
    IEinvoiceSettingsService settingsService,
    IEinvoiceService einvoiceService,
    IIrpClient irpClient,
    IClock clock) : IEwayBillService
{
    private readonly IUnitOfWork _unitOfWork = unitOfWork
        ?? throw new ArgumentNullException(nameof(unitOfWork));

    private readonly ICompanyContext _companyContext = companyContext
        ?? throw new ArgumentNullException(nameof(companyContext));

    private readonly IEinvoiceSettingsService _settingsService = settingsService
        ?? throw new ArgumentNullException(nameof(settingsService));

    private readonly IEinvoiceService _einvoiceService = einvoiceService
        ?? throw new ArgumentNullException(nameof(einvoiceService));

    private readonly IIrpClient _irpClient = irpClient
        ?? throw new ArgumentNullException(nameof(irpClient));

    private readonly IClock _clock = clock ?? throw new ArgumentNullException(nameof(clock));

    /// <inheritdoc />
    public async Task<IReadOnlyList<EwayBillSummary>> ListAsync(
        CancellationToken cancellationToken = default)
    {
        var companyId = await _companyContext.EnsureCompanyAsync(cancellationToken).ConfigureAwait(false);

        return (await _unitOfWork.Repository<EwayBill>()
                .ListAsync(new BillsOfCompany(companyId), cancellationToken)
                .ConfigureAwait(false))
            .OrderByDescending(bill => bill.GeneratedAtUtc ?? DateTimeOffset.MinValue)
            .Select(ToSummary)
            .ToList();
    }

    /// <inheritdoc />
    public async Task<EwayBillSummary?> FindByDocumentAsync(
        Guid tradeDocumentId,
        CancellationToken cancellationToken = default)
    {
        var companyId = await _companyContext.EnsureCompanyAsync(cancellationToken).ConfigureAwait(false);

        var bill = await FindBillAsync(companyId, tradeDocumentId, cancellationToken).ConfigureAwait(false);

        return bill is null ? null : ToSummary(bill);
    }

    /// <inheritdoc />
    public async Task<bool> IsRequiredForDocumentAsync(
        Guid tradeDocumentId,
        CancellationToken cancellationToken = default)
    {
        var companyId = await _companyContext.EnsureCompanyAsync(cancellationToken).ConfigureAwait(false);
        var settings = await _settingsService.GetEntityAsync(cancellationToken).ConfigureAwait(false);

        var document = await RequireDocumentAsync(companyId, tradeDocumentId, cancellationToken)
            .ConfigureAwait(false);

        return EwayBillThresholdRule.IsRequired(
            ConsignmentValueMinor(document), settings.EwayBillThresholdMinor);
    }

    /// <inheritdoc />
    public async Task<EwayBillSummary> GenerateAsync(
        Guid tradeDocumentId,
        int distanceKilometres,
        EwayBillPartB partB,
        CancellationToken cancellationToken = default)
    {
        ArgumentNullException.ThrowIfNull(partB);

        var companyId = await _companyContext.EnsureCompanyAsync(cancellationToken).ConfigureAwait(false);
        var document = await RequireDocumentAsync(companyId, tradeDocumentId, cancellationToken)
            .ConfigureAwait(false);

        var existing = await FindBillAsync(companyId, tradeDocumentId, cancellationToken)
            .ConfigureAwait(false);

        if (existing is { Status: EwayBillStatus.Active })
        {
            throw new InvalidOperationException(
                $"This document already has an active e-way bill ({existing.EwayBillNumber}). Cancel "
                + "it before generating another.");
        }

        // Generated by IRN when the invoice has one — the route the spec asks for (C6.2).
        var registration = await _einvoiceService
            .FindByDocumentAsync(tradeDocumentId, cancellationToken)
            .ConfigureAwait(false);

        var irn = registration is { Status: EinvoiceStatus.Generated } ? registration.Irn : null;

        var bill = existing ?? new EwayBill(
            companyId,
            tradeDocumentId,
            ConsignmentValueMinor(document),
            distanceKilometres,
            irn);

        bill.SetPartB(
            partB.TransportMode,
            partB.VehicleType,
            partB.VehicleNumber,
            partB.TransporterGstin,
            partB.TransporterName,
            partB.TransportDocumentNumber,
            partB.TransportDocumentDate);

        if (existing is null)
        {
            await _unitOfWork.Repository<EwayBill>().AddAsync(bill, cancellationToken)
                .ConfigureAwait(false);
        }
        else
        {
            _unitOfWork.Repository<EwayBill>().Update(bill);
        }

        // Saved before the call, for the same reason e-invoice registrations are: a bill the portal
        // issued and we failed to record is worse than a draft row nobody used.
        await _unitOfWork.SaveChangesAsync(cancellationToken).ConfigureAwait(false);

        var credentials = await _settingsService.ResolveCredentialsAsync(cancellationToken)
            .ConfigureAwait(false);

        var response = irn is null
            ? throw new InvalidOperationException(
                "This invoice has no IRN yet. Register the e-invoice first — Phase 6 generates e-way "
                + "bills by IRN (phase-6-einvoice-eway.md §2, C6.2).")
            : await _irpClient
                .GenerateEwayBillByIrnAsync(credentials, irn, partB, distanceKilometres, cancellationToken)
                .ConfigureAwait(false);

        if (response.Call.Succeeded && response.EwayBillNumber is { } number)
        {
            bill.MarkGenerated(number, ParsePortalTimestamp(response.GeneratedDateText) ?? _clock.UtcNow);

            // The portal's own expiry wins over our slab arithmetic whenever it states one.
            if (ParsePortalTimestamp(response.ValidUntilText) is { } validUntil
                && bill.ValidUntilUtc is { } computed
                && validUntil >= computed)
            {
                bill.MarkExtended(validUntil, bill.DistanceKilometres);
            }
        }
        else
        {
            bill.MarkRejected(response.Call.ErrorMessage ?? "The portal did not issue an e-way bill.");
        }

        _unitOfWork.Repository<EwayBill>().Update(bill);
        await _unitOfWork.SaveChangesAsync(cancellationToken).ConfigureAwait(false);

        return ToSummary(bill);
    }

    /// <inheritdoc />
    public async Task<EwayBillSummary> UpdatePartBAsync(
        Guid ewayBillId,
        EwayBillPartB partB,
        CancellationToken cancellationToken = default)
    {
        ArgumentNullException.ThrowIfNull(partB);

        var bill = await RequireBillAsync(ewayBillId, cancellationToken).ConfigureAwait(false);

        if (bill.EwayBillNumber is not { } number)
        {
            throw new InvalidOperationException(
                "Part-B can only be updated on a bill the portal has issued.");
        }

        var credentials = await _settingsService.ResolveCredentialsAsync(cancellationToken)
            .ConfigureAwait(false);

        var response = await _irpClient
            .UpdateEwayBillPartBAsync(credentials, number, partB, cancellationToken)
            .ConfigureAwait(false);

        if (!response.Call.Succeeded)
        {
            throw new InvalidOperationException(
                $"The portal did not accept the Part-B update: {response.Call.ErrorMessage}");
        }

        bill.SetPartB(
            partB.TransportMode,
            partB.VehicleType,
            partB.VehicleNumber,
            partB.TransporterGstin,
            partB.TransporterName,
            partB.TransportDocumentNumber,
            partB.TransportDocumentDate);

        _unitOfWork.Repository<EwayBill>().Update(bill);
        await _unitOfWork.SaveChangesAsync(cancellationToken).ConfigureAwait(false);

        return ToSummary(bill);
    }

    /// <inheritdoc />
    public async Task<EwayBillSummary> CancelAsync(
        Guid ewayBillId,
        string reasonCode,
        string? remarks = null,
        CancellationToken cancellationToken = default)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(reasonCode);

        var bill = await RequireBillAsync(ewayBillId, cancellationToken).ConfigureAwait(false);
        var now = _clock.UtcNow;

        if (!bill.CanCancelAt(now))
        {
            throw new InvalidOperationException(
                "An e-way bill can only be cancelled within 24 hours of generation.");
        }

        var credentials = await _settingsService.ResolveCredentialsAsync(cancellationToken)
            .ConfigureAwait(false);

        var response = await _irpClient
            .CancelEwayBillAsync(credentials, bill.EwayBillNumber!.Value, reasonCode, remarks, cancellationToken)
            .ConfigureAwait(false);

        if (!response.Call.Succeeded)
        {
            throw new InvalidOperationException(
                $"The portal did not cancel this e-way bill: {response.Call.ErrorMessage}");
        }

        bill.MarkCancelled(now, reasonCode, remarks);

        _unitOfWork.Repository<EwayBill>().Update(bill);
        await _unitOfWork.SaveChangesAsync(cancellationToken).ConfigureAwait(false);

        return ToSummary(bill);
    }

    /// <inheritdoc />
    public async Task<EwayBillSummary> ExtendValidityAsync(
        Guid ewayBillId,
        int remainingDistanceKilometres,
        string reasonCode,
        string? remarks = null,
        CancellationToken cancellationToken = default)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(reasonCode);

        var bill = await RequireBillAsync(ewayBillId, cancellationToken).ConfigureAwait(false);

        if (bill.EwayBillNumber is not { } number)
        {
            throw new InvalidOperationException("Only an issued e-way bill can be extended.");
        }

        var credentials = await _settingsService.ResolveCredentialsAsync(cancellationToken)
            .ConfigureAwait(false);

        var response = await _irpClient
            .ExtendEwayBillValidityAsync(
                credentials, number, remainingDistanceKilometres, reasonCode, remarks, cancellationToken)
            .ConfigureAwait(false);

        if (!response.Call.Succeeded)
        {
            throw new InvalidOperationException(
                $"The portal did not extend this e-way bill: {response.Call.ErrorMessage}");
        }

        var granted = ParsePortalTimestamp(response.ValidUntilText)
            ?? throw new InvalidOperationException(
                "The portal accepted the extension but returned no new expiry.");

        bill.MarkExtended(granted, remainingDistanceKilometres);

        _unitOfWork.Repository<EwayBill>().Update(bill);
        await _unitOfWork.SaveChangesAsync(cancellationToken).ConfigureAwait(false);

        return ToSummary(bill);
    }

    /// <summary>
    /// The consignment value: every line's taxable value plus the tax on it. This is what the
    /// threshold is tested against, and it is read from the posted snapshot rather than recomputed.
    /// </summary>
    private static long ConsignmentValueMinor(TradeDocument document) =>
        document.Lines.Sum(line =>
            line.TaxableValueMinor
            + line.IgstMinor
            + line.CgstMinor
            + line.SgstMinor
            + line.CessMinor);

    /// <summary>
    /// Reads a NIC timestamp. They arrive as IST without an offset, so the offset is stated here
    /// instead of inherited from the host — a machine set to another timezone would otherwise move an
    /// expiry that a roadside check reads off the bill.
    /// </summary>
    private static DateTimeOffset? ParsePortalTimestamp(string? text) =>
        string.IsNullOrWhiteSpace(text)
            ? null
            : DateTime.TryParse(text, CultureInfo.InvariantCulture, DateTimeStyles.None, out var parsed)
                ? new DateTimeOffset(parsed, IndianStandardTimeOffset).ToUniversalTime()
                : null;

    private static readonly TimeSpan IndianStandardTimeOffset = new(5, 30, 0);

    private async Task<TradeDocument> RequireDocumentAsync(
        Guid companyId,
        Guid tradeDocumentId,
        CancellationToken cancellationToken) =>
        await _unitOfWork.Repository<TradeDocument>()
            .SingleOrDefaultAsync(new DocumentWithLines(companyId, tradeDocumentId), cancellationToken)
            .ConfigureAwait(false)
        ?? throw new InvalidOperationException("This document is not in this company's books.");

    private async Task<EwayBill> RequireBillAsync(Guid ewayBillId, CancellationToken cancellationToken)
    {
        var companyId = await _companyContext.EnsureCompanyAsync(cancellationToken).ConfigureAwait(false);

        var bill = await _unitOfWork.Repository<EwayBill>()
            .GetByIdAsync(ewayBillId, cancellationToken)
            .ConfigureAwait(false);

        return bill is null || bill.CompanyId != companyId
            ? throw new InvalidOperationException("This e-way bill is not in this company's books.")
            : bill;
    }

    private async Task<EwayBill?> FindBillAsync(
        Guid companyId,
        Guid tradeDocumentId,
        CancellationToken cancellationToken) =>
        await _unitOfWork.Repository<EwayBill>()
            .SingleOrDefaultAsync(new BillOfDocument(companyId, tradeDocumentId), cancellationToken)
            .ConfigureAwait(false);

    private static EwayBillSummary ToSummary(EwayBill bill) =>
        new(bill.Id,
            bill.TradeDocumentId,
            bill.Irn,
            bill.EwayBillNumber,
            bill.Status,
            bill.ConsignmentValueMinor,
            bill.DistanceKilometres,
            bill.TransportMode,
            bill.VehicleType,
            bill.VehicleNumber,
            bill.TransporterGstin,
            bill.TransporterName,
            bill.TransportDocumentNumber,
            bill.TransportDocumentDate,
            bill.GeneratedAtUtc,
            bill.ValidUntilUtc,
            bill.IsPartBComplete,
            bill.LastErrorText);

    private sealed class BillsOfCompany : Specification<EwayBill>
    {
        public BillsOfCompany(Guid companyId)
        {
            Where(bill => bill.CompanyId == companyId);
            ApplyNoTracking();
        }
    }

    private sealed class BillOfDocument : Specification<EwayBill>
    {
        public BillOfDocument(Guid companyId, Guid tradeDocumentId) =>
            Where(bill => bill.CompanyId == companyId && bill.TradeDocumentId == tradeDocumentId);
    }

    private sealed class DocumentWithLines : Specification<TradeDocument>
    {
        public DocumentWithLines(Guid companyId, Guid documentId)
        {
            Where(document => document.CompanyId == companyId && document.Id == documentId);
            AddInclude(document => document.Lines);
            ApplyNoTracking();
        }
    }
}
